        let read_line = bounded.read_line(&mut line);
        match read_line.await {
            Ok(0) => break, // クライアントの切断
            Ok(_) => {}
            Err(_) => break,
        }
        if line.len() > MAX_CMD_LINE {
            break; // 過大なコマンド行: クライアントが壊れているか悪意がある
        }
